            header=lines[i]
            def cols(row):
                row=row.strip()
                if row.startswith('|'): row=row[1:]
                if row.endswith('|'): row=row[:-1]
                # count unescaped pipes
                return len(re.split(r'(?<!\\)\|', row))
            n=cols(header)
